/* Lomenti Call: bilingual client questions. Contract draft 03.11.2026; not legal advice. */
const FAQ_GROUPS=[["Цена и оплата","Cena un apmaksa",[["Сколько стоит сайт?","Cik maksā mājaslapa?","Базовый сайт Start стоит 50 € в месяц уже с НДС. За первый год это 600 € с НДС, разделённые на 12 платежей. Из них 480 € приходится на разработку и 120 € — на сопровождение. В сумму не входят домен, хостинг и дополнительные функции, которые мы согласуем отдельно.","Start mājaslapa maksā 50 € mēnesī, jau ar PVN. Pirmajā gadā kopā tie ir 600 € ar PVN, sadalīti 12 maksājumos. No tiem 480 € ir izstrāde un 120 € — atbalsts. Domēns, hostings un papildu funkcijas nav iekļautas; tās saskaņojam atsevišķi."],["Почему ежемесячная оплата?","Kāpēc ikmēneša maksājumi?","Чтобы распределить стоимость разработки и поддержки без большого первоначального платежа. Первый платёж составляет всего 50 €, а не всю стоимость сайта.","Lai sadalītu izstrādes un atbalsta izmaksas bez lielas sākotnējās iemaksas. Pirmais maksājums ir tikai 50 €, nevis visa vietnes cena."],["Что входит в 50 €?","Kas iekļauts 50 €?","За 50 € в месяц, уже с НДС, мы создаём сайт до пяти информационных страниц с адаптивным дизайном, согласованными формами и необходимыми языковыми версиями. В первый год также входят сопровождение и две небольшие правки контента ежемесячно. Домен и хостинг оплачиваются отдельно. Сначала согласуем список страниц, языки и формы, чтобы было понятно, что вы получаете.","Par 50 € mēnesī, jau ar PVN, izveidojam mājaslapu ar līdz piecām informatīvām lapām, adaptīvu dizainu, saskaņotām formām un nepieciešamajām valodu versijām. Pirmajā gadā iekļauts arī atbalsts un divi nelieli satura labojumi mēnesī. Domēns un hostings tiek apmaksāti atsevišķi. Vispirms saskaņosim lapas, valodas un formas, lai būtu skaidrs, ko saņemsiet."],["Сколько за первый год?","Cik jāmaksā pirmajā gadā?","За первый год — 600 € с НДС, то есть по 50 € в месяц. Отдельно оплачиваются только заранее согласованные дополнительные услуги, например домен или хостинг. Это фиксированная стоимость Start; домен и хостинг выбираете и оплачиваете отдельно.","Pirmajā gadā — 600 € ar PVN jeb 50 € mēnesī. Atsevišķi maksā tikai par iepriekš saskaņotiem papildu pakalpojumiem, piemēram, domēnu vai hostingu. Tā ir fiksēta Start cena; domēnu un hostingu izvēlaties un apmaksājat atsevišķi."],["Есть первый взнос?","Vai ir pirmā iemaksa?","50 € после договора, до начала работ; входит в общую сумму. Это не дополнительная комиссия: платёж засчитывается как первый из двенадцати.","50 € pēc līguma, pirms darbu sākuma; iekļauti kopējā cenā. Tā nav papildu maksa: iemaksa ir pirmais no divpadsmit maksājumiem."],["Когда первый платёж?","Kad jāveic pirmais maksājums?","После заключения договора и до начала разработки. После согласования условий направим счёт; до его оплаты разработку не начинаем.","Pēc līguma noslēgšanas un pirms izstrādes sākuma. Pēc nosacījumu saskaņošanas nosūtīsim rēķinu; izstrādi sākam pēc apmaksas."],["Можно оплатить сразу?","Vai var samaksāt uzreiz?","Стандартно 12 платежей; единовременную оплату согласует команда. Если вам удобнее один платёж, передадим запрос команде и подтвердим условия письменно.","Standartā 12 maksājumi; vienreizēju apmaksu saskaņo komanda. Ja ērtāks viens maksājums, nodosim pieprasījumu komandai un rakstiski apstiprināsim nosacījumus."],["Можно банковским переводом?","Vai var maksāt ar pārskaitījumu?","Выставляем счета с реквизитами; способ оплаты подтвердим до договора. В счёте будут указаны сумма, назначение платежа и реквизиты получателя.","Izrakstām rēķinus ar rekvizītiem; maksāšanas veidu precizēsim pirms līguma. Rēķinā būs summa, maksājuma mērķis un saņēmēja rekvizīti."],["Есть официальные счета?","Vai izrakstāt rēķinus?","Да, выставление счетов предусмотрено договором. Счета помогут вашей бухгалтерии учитывать платежи по договору.","Jā, līgums paredz rēķinu izrakstīšanu. Rēķini palīdzēs jūsu grāmatvedībai uzskaitīt maksājumus pēc līguma."],["Цена с НДС?","Vai cenā iekļauts PVN?","Да, конечно. Указанные 50 € в месяц — это уже окончательная цена с НДС. Дополнительно НДС к этой сумме не прибавляется. То есть к объявленным 50 € ничего сверху за НДС не добавляется.","Jā, protams. Norādītie 50 € mēnesī jau ir gala cena ar PVN. Papildu PVN šai summai netiek pieskaitīts. Tātad norādītajiem 50 € PVN papildus netiek pieskaitīts."],["Есть скрытые платежи?","Vai ir slēptas izmaksas?","Нет, дополнительные работы мы не начинаем без вашего письменного согласия. Сразу уточним только один момент: домен, хостинг и сторонние сервисы оплачиваются отдельно, поэтому их стоимость обсудим заранее. Любую новую функцию или работу сначала оценим и только потом попросим подтверждение.","Nē, papildu darbus neveicam bez jūsu rakstiskas piekrišanas. Vienīgi domēns, hostings un trešo pušu pakalpojumi tiek apmaksāti atsevišķi, tādēļ to izmaksas izrunāsim iepriekš. Jebkuru jaunu funkciju vai darbu vispirms novērtēsim un tikai tad lūgsim apstiprinājumu."],["Сколько стоят домен и хостинг?","Cik maksā domēns un hostings?","Обычно для небольшого сайта можно ориентироваться на хостинг примерно от 3–5 € в месяц, а более функциональные варианты могут стоить 5–10 € и выше. Это примерный ориентир, не фиксированный тариф: точную цену подберём вместе с вами у провайдера. Домен оплачивается отдельно, и оба аккаунта будут оформлены на вас. Точная сумма зависит от выбранного поставщика, объёма ресурсов и срока оплаты.","Nelielai mājaslapai orientējoša hostinga cena var sākties aptuveni no 3–5 € mēnesī, savukārt plašāki risinājumi var maksāt 5–10 € vai vairāk. Tā ir aptuvena norāde, nevis fiksēta cena: precīzu piedāvājumu palīdzēsim izvēlēties pie pakalpojumu sniedzēja. Domēns tiek apmaksāts atsevišķi, un abi konti būs uz jūsu vārda. Precīza summa atkarīga no pakalpojumu sniedzēja, resursiem un apmaksas perioda."],["Сколько стоит несколько языков?","Cik maksā vairākas valodas?","Языковые версии уже входят в стоимость сайта Start. Мы заранее уточним, какие языки вам нужны, чтобы правильно подготовить структуру и содержание. Если потребуется профессиональный перевод текстов или нестандартная функциональность, это отдельно обсудим до начала работ. Нужные языки укажем в задании; отдельно уточним, кто предоставляет готовые переводы.","Start mājaslapas cenā jau ir iekļautas valodu versijas. Iepriekš precizēsim, kuras valodas jums nepieciešamas, lai pareizi sagatavotu struktūru un saturu. Ja būs vajadzīgs profesionāls tekstu tulkojums vai nestandarta funkcijas, to atsevišķi apspriedīsim pirms darbu sākuma. Nepieciešamās valodas norādīsim uzdevumā; atsevišķi precizēsim, kurš sagādā tulkojumus."],["Цена дополнительных страниц?","Cik maksā papildu lapas?","Конечно, мы всегда рады помочь, если вашему бизнесу нужно больше пяти страниц. Расскажите, что именно вы хотели бы добавить, и мы вместе найдём удобное решение — расширим сайт или предложим альтернативную структуру. Дополнительный объём и стоимость обязательно согласуем с вами заранее. Мы можем предложить объединить похожие разделы или расширить сайт, если это удобнее посетителям.","Protams, ar prieku palīdzēsim, ja jūsu uzņēmumam vajadzīgas vairāk nekā piecas lapas. Pastāstiet, ko vēlaties pievienot, un kopā atradīsim piemērotāko risinājumu — paplašināsim vietni vai piedāvāsim citu struktūru. Papildu darbu apjomu un cenu vienmēr saskaņosim iepriekš. Varam piedāvāt apvienot līdzīgas sadaļas vai paplašināt vietni, ja tā apmeklētājiem būs ērtāk."],["Что при просрочке платежа?","Kas notiek, ja maksājums kavējas?","После 14 дней просрочки и письменного предупреждения возможна приостановка работ и поддержки; ваш хостинг не отключаем. Если возникнут сложности с оплатой, лучше сообщить заранее — обсудим возможный порядок действий.","Pēc 14 dienu kavējuma un rakstiska brīdinājuma darbus un atbalstu var apturēt; jūsu hostingu neatslēdzam. Ja rodas maksājuma grūtības, labāk paziņot iepriekš — apspriedīsim iespējamo risinājumu."],["Могут ли цены измениться?","Vai cena var mainīties?","Нет, согласованная цена тарифа Start в течение первого года не меняется — всё строго по договору. Конечно, со временем у бизнеса могут появиться новые задачи. Мы заранее обсудим любые изменения и, если потребуется, предложим дополнительные услуги только с вашего согласия. Никаких неожиданных доплат. Изменение объёма работ не означает автоматического изменения базовой цены.","Nē, Start tarifa saskaņotā cena pirmā gada laikā nemainās — viss notiek stingri saskaņā ar līgumu. Protams, uzņēmumam laika gaitā var rasties jaunas vajadzības. Jebkuras izmaiņas apspriedīsim iepriekš un papildu pakalpojumus piedāvāsim tikai ar jūsu piekrišanu. Nekādu negaidītu piemaksu. Darbu apjoma maiņa nenozīmē automātisku pamatcenas maiņu."],["Сколько поддержка после года?","Cik maksā atbalsts pēc gada?","После первого года сопровождение стоит 50 € в месяц, уже с НДС, пока действует договор поддержки. Если поддержка больше не нужна, после первого года её можно прекратить с письменным предупреждением за 30 дней.","Pēc pirmā gada atbalsts maksā 50 € mēnesī, jau ar PVN, kamēr ir spēkā atbalsta līgums. Ja atbalsts vairs nav vajadzīgs, pēc pirmā gada to var izbeigt ar rakstisku 30 dienu brīdinājumu."],["Почему после года тоже 50 €?","Kāpēc pēc gada arī 50 €?","После первого года разработка уже оплачена, а 50 € в месяц относятся к дальнейшему сопровождению по договору. Если ваш бизнес развивается и сайту понадобится больше внимания, мы можем отдельно предложить расширенную поддержку: команда возьмёт на себя согласованный дополнительный объём работ за отдельную плату. Всё заранее обсудим, чтобы вы понимали, за что платите. Базовый объём поддержки остаётся тем, что согласован в договоре; новые задачи оцениваются отдельно.","Pēc pirmā gada izstrāde jau ir apmaksāta, bet 50 € mēnesī attiecas uz turpmāko atbalstu saskaņā ar līgumu. Ja jūsu uzņēmums attīstās un vietnei nepieciešama plašāka aprūpe, varam atsevišķi piedāvāt paplašinātu atbalstu: komanda uzņemsies saskaņotus papildu darbus par atsevišķu samaksu. Visu iepriekš izrunāsim, lai izmaksas būtu skaidras. Atbalsta pamatapjoms paliek līgumā saskaņotais; jaunus uzdevumus vērtē atsevišķi."],["Можно без поддержки?","Vai var bez atbalsta?","Другой вариант сотрудничества обсуждается индивидуально. Если нужен другой формат, сначала уточним, кто будет обновлять сайт и отвечать за техническую часть.","Citu sadarbības modeli apspriežam individuāli. Ja vajadzīgs cits modelis, vispirms precizēsim, kurš atjauninās vietni un atbildēs par tehnisko daļu."],["Скидка за несколько сайтов?","Vai ir atlaide vairākām vietnēm?","У нас прозрачная стоимость и понятные условия, поэтому мы не обещаем скидку автоматически. Мы можем создать сайт, помочь с настройкой домена и подобрать подходящий формат работы. Если у вас несколько проектов или вы планируете регулярно развивать сайты, давайте обсудим долгосрочное сотрудничество: так проще выстроить удобный процесс обновлений и подобрать решение под ваши задачи. Для нескольких проектов можем обсудить общий план работ, сроки и сопровождение, не обещая несогласованных скидок.","Mums ir skaidras cenas un sadarbības nosacījumi, tāpēc automātisku atlaidi nesolām. Varam izveidot vietni, palīdzēt iestatīt domēnu un izvēlēties piemērotu sadarbības veidu. Ja jums ir vairāki projekti vai plānojat regulāri attīstīt vietnes, apspriedīsim ilgtermiņa sadarbību — tā var ērtāk organizēt atjauninājumus un atrast jūsu vajadzībām atbilstošu risinājumu. Vairākiem projektiem varam apspriest kopīgu darbu plānu, termiņus un atbalstu, nesolot nesaskaņotas atlaides."]]],["Возможности сайта","Mājaslapas iespējas",[["Как будет выглядеть сайт?","Kā izskatīsies vietne?","Дизайн согласуем под компанию, покажем первый вариант. Сначала узнаем, какие услуги вы предлагаете и какой стиль вам близок, затем согласуем направление дизайна.","Dizainu saskaņosim ar uzņēmumu, parādīsim pirmo variantu. Vispirms noskaidrosim jūsu pakalpojumus un vēlamo stilu, tad saskaņosim dizaina virzienu."],["Есть примеры работ?","Vai ir darbu piemēri?","Да, покажем проекты и концепты, отдельно обозначив демонстрационные. Покажем, какие решения демонстрационные, а какие реализованы для заказчиков.","Jā, parādīsim projektus un konceptus, skaidri norādot demonstrācijas. Skaidri parādīsim, kuri risinājumi ir demonstrācijas un kuri īstenoti klientiem."],["Сайт уникальный или шаблон?","Vai vietne būs unikāla vai veidne?","Дизайн согласуется индивидуально; общие технические компоненты могут использоваться повторно. Внешний вид и содержание подбираются под ваш бизнес, а не копируются с чужого сайта.","Dizainu saskaņo individuāli; kopīgus tehniskos komponentus var izmantot atkārtoti. Izskatu un saturu pielāgojam jūsu uzņēmumam, nevis kopējam no citas vietnes."],["Какие пять страниц?","Kuras piecas lapas?","Например, главная, услуги, о нас, работы, контакты; точный список согласуем. Например, если важнее каталог услуг, можем изменить набор страниц до утверждения задания.","Piemēram, sākums, pakalpojumi, par mums, darbi, kontakti; precīzu sarakstu saskaņosim. Piemēram, ja svarīgāks pakalpojumu katalogs, lapu sastāvu varam mainīt pirms uzdevuma apstiprināšanas."],["Можно свою структуру?","Vai var izvēlēties struktūru?","Да, в пределах согласованного задания. Поможем определить, какую информацию клиент должен увидеть первой и как быстро найти контакты.","Jā, saskaņotā darba uzdevuma ietvaros. Palīdzēsim noteikt, ko apmeklētājam redzēt vispirms un kā ātri atrast kontaktus."],["Будет работать на телефоне?","Vai darbosies telefonā?","Да, обязательно. В тариф Start входит адаптивный дизайн, поэтому сайт будет подстраиваться под экран телефона, планшета и компьютера. Отдельно проверим удобство чтения, навигации и отправки заявок на небольшом экране.","Jā, noteikti. Start tarifā ir iekļauts adaptīvs dizains, tāpēc vietne pielāgosies telefonam, planšetei un datoram. Atsevišķi pārbaudīsim lasāmību, navigāciju un pieteikumu nosūtīšanu mazā ekrānā."],["Можно форму обратной связи?","Vai var pievienot saziņas formu?","Да, согласованные формы входят в Start. Заранее согласуем поля формы и адрес, на который должны приходить сообщения.","Jā, saskaņotas formas ietilpst Start. Iepriekš saskaņosim formas laukus un adresi, uz kuru sūtīt ziņojumus."],["Фото, видео и галерея?","Foto, video un galerija?","Возможность и объём согласуем в задании. Важно заранее определить количество материалов и кто предоставит права на их использование.","Iespējas un apjomu saskaņosim uzdevumā. Svarīgi iepriekš noteikt materiālu daudzumu un to izmantošanas tiesības."],["Можно прайс-лист?","Vai var ievietot cenrādi?","Да, формат согласуем при подготовке содержания. Прайс можно разместить на отдельной странице или внутри раздела услуг — как удобнее вашим клиентам.","Jā, formātu saskaņosim, gatavojot saturu. Cenrādi var ievietot atsevišķā lapā vai pakalpojumu sadaļā — kā ērtāk klientiem."],["Каталог без онлайн-оплаты?","Katalogs bez tiešsaistes apmaksas?","Можем оценить отдельно; сложный каталог не включён автоматически в Start. Уточним количество позиций, фильтры и необходимость частого обновления информации.","Varam izvērtēt atsevišķi; sarežģīts katalogs nav automātiski iekļauts Start. Precizēsim pozīciju skaitu, filtrus un to, cik bieži informācija būs jāatjaunina."],["Можно онлайн-запись?","Vai var pievienot pierakstu?","Оценим интеграцию и стоимость отдельно. Нужно понять, хотите ли вы просто принимать запросы или синхронизировать свободное время с календарём.","Integrāciju un cenu izvērtēsim atsevišķi. Jāsaprot, vai vēlaties tikai saņemt pieprasījumus vai sinhronizēt brīvos laikus ar kalendāru."],["Можно WhatsApp и мессенджеры?","Vai var pievienot WhatsApp?","Ссылки и интеграции возможны по согласованию; автоматизация оценивается отдельно. Обычная кнопка связи и полноценная автоматическая интеграция — разные по объёму задачи.","Saites un integrācijas var saskaņot; automatizāciju vērtē atsevišķi. Parasta saziņas poga un pilna automātiska integrācija ir atšķirīga apjoma darbi."],["Несколько языков?","Vairākas valodas?","Да, конечно. Языковые версии входят в стоимость Start. Просто уточним, какие языки вам нужны и кто предоставляет готовые тексты, чтобы сайт был удобен для ваших клиентов. До начала работ согласуем перечень языков и наличие текстов для каждой версии.","Jā, protams. Valodu versijas ir iekļautas Start cenā. Tikai precizēsim, kuras valodas jums vajadzīgas un kurš sagatavo tekstus, lai vietne būtu ērta jūsu klientiem. Pirms darbu sākuma saskaņosim valodas un tekstu pieejamību katrai versijai."],["Кто готовит тексты и фото?","Kas sagatavo tekstus un foto?","Ответственность указывается в приложении; обычно нужны материалы клиента. Если материалов пока нет, можем обсудить помощь с подготовкой, но не будем обещать её бесплатно без согласования.","Atbildību norāda pielikumā; parasti vajadzīgi klienta materiāli. Ja materiālu vēl nav, varam apspriest palīdzību sagatavošanā, bet nesolīsim to bez maksas bez vienošanās."],["Можно менять информацию самому?","Vai var pašam mainīt saturu?","Зависит от системы; панель управления согласуется отдельно. Если вам важно часто менять цены или товары, скажите об этом заранее — подберём подходящий способ управления.","Atkarīgs no sistēmas; administrēšanas paneli saskaņo atsevišķi. Ja bieži jāmaina cenas vai preces, pastāstiet iepriekš — izvēlēsimies piemērotu pārvaldības veidu."],["Можно подключить аналитику?","Vai var pievienot analītiku?","Обсудим сервис, настройку и требования к данным. Например, можно обсуждать статистику посещений и отправленных форм; выбор сервиса влияет на настройки конфиденциальности.","Apspriedīsim rīku, uzstādīšanu un datu prasības. Piemēram, var skatīt apmeklējumus un nosūtītās formas; rīka izvēle ietekmē privātuma iestatījumus."],["Будет в Google?","Vai vietne būs Google?","Индексацию и позиции гарантировать нельзя; технические меры обсудим. Мы можем обсудить техническую подготовку сайта к поиску, но позиция в выдаче зависит не только от разработки.","Indeksēšanu un pozīcijas garantēt nevar; tehniskos pasākumus apspriedīsim. Varam apspriest vietnes tehnisko sagatavošanu meklētājiem, bet pozīcija nav atkarīga tikai no izstrādes."],["Делаете SEO?","Vai piedāvājat SEO?","SEO-работы согласуются отдельно, Start не гарантирует продвижение. Если продвижение важно, определим конкретные работы и отдельный бюджет до их начала.","SEO darbus saskaņo atsevišķi; Start negarantē virzīšanu meklētājos. Ja meklētāju optimizācija ir svarīga, pirms sākuma noteiksim konkrētus darbus un budžetu."],["Гарантируете новых клиентов?","Vai garantējat jaunus klientus?","Мы не хотим обещать вам цифры, на которые нельзя честно повлиять. Хороший сайт может помочь клиентам найти информацию и связаться с вами, но конкретное количество заявок или продаж мы не гарантируем. Наша задача — сделать понятный и удобный инструмент для связи с вами, а не обещать заранее число продаж.","Nevēlamies solīt rezultātus, kurus nevaram godīgi garantēt. Laba vietne var palīdzēt klientiem atrast informāciju un sazināties ar jums, taču konkrētu pieteikumu vai pārdošanas skaitu negarantējam. Mūsu uzdevums ir radīt saprotamu saziņas rīku, nevis iepriekš solīt pārdošanas apjomu."],["Можно расширить до магазина?","Vai var vēlāk izveidot veikalu?","Да, как отдельный проект после оценки. При расширении оценим каталог, корзину, оплату, доставку и сохранность существующего содержания.","Jā, kā atsevišķu projektu pēc izvērtēšanas. Paplašinot izvērtēsim katalogu, grozu, apmaksu, piegādi un esošā satura saglabāšanu."]]],["Сроки и процесс","Termiņi un process",[["За сколько дней сделаете?","Cik dienās izstrādāsiet?","Срок укажем в приложении после оценки объёма и материалов. На сроки влияют число страниц, готовность материалов, согласования и дополнительные функции.","Termiņu norādīsim pielikumā pēc apjoma un materiālu izvērtēšanas. Termiņu ietekmē lapu skaits, materiālu gatavība, saskaņojumi un papildu funkcijas."],["Когда начнёте?","Kad sāksiet?","После договора, первого платежа и получения материалов; дату уточним. Чтобы не терять время, заранее соберём всё необходимое и определим порядок согласований.","Pēc līguma, pirmā maksājuma un materiālu saņemšanas; datumu precizēsim. Lai netērētu laiku, iepriekš savāksim vajadzīgo un vienosimies par saskaņošanas kārtību."],["Что нужно от меня?","Kas jums vajadzīgs no manis?","Задание, тексты, изображения, доступы и согласования. Если чего-то не хватает, составим конкретный список, чтобы вам не приходилось угадывать.","Uzdevums, teksti, attēli, piekļuves un saskaņojumi. Ja kaut kā trūkst, sagatavosim konkrētu sarakstu, lai jums nebūtu jāmin."],["Кто делает проект?","Kas izstrādās projektu?","Команда Lomenti; ответственное лицо укажем в документах. Вы будете знать, кому направлять материалы, замечания и вопросы по проекту.","Lomenti komanda; atbildīgo personu norādīsim dokumentos. Jūs zināsiet, kam sūtīt materiālus, piezīmes un jautājumus par projektu."],["Можно срочно?","Vai var steidzami?","Проверим возможность, срок и стоимость отдельно. Ускорение возможно не всегда, поэтому подтвердим реальный график до обещания даты.","Atsevišķi pārbaudīsim iespēju, termiņu un cenu. Paātrināšana ne vienmēr ir iespējama, tāpēc reālu grafiku apstiprināsim pirms datuma solīšanas."],["Когда первый дизайн?","Kad būs pirmais dizains?","Дату согласуем в плане проекта. Перед первым показом определим содержание страниц и основное визуальное направление.","Datumu saskaņosim projekta plānā. Pirms pirmās prezentācijas noteiksim lapu saturu un galveno vizuālo virzienu."],["Можно следить за процессом?","Vai var sekot procesam?","Согласуем порядок и частоту обновлений. Уточним, как вам удобнее получать промежуточные результаты и оставлять комментарии.","Saskaņosim informēšanas kārtību un biežumu. Precizēsim, kā jums ērtāk saņemt starprezultātus un iesniegt komentārus."],["Если не понравится дизайн?","Ja dizains nepatiks?","После первого варианта предусмотрен раунд изменений. Лучше собрать замечания одним списком — так проще ничего не упустить и быстрее внести правки.","Pēc pirmā varianta paredzēta labojumu kārta. Labāk apkopot piezīmes vienā sarakstā — tā vieglāk neko nepalaist garām un ātrāk veikt labojumus."],["Сколько раундов изменений?","Cik labojumu kārtu?","Два раунда по умолчанию; новые функции отдельно. Один раунд — это согласованный список изменений, а не одна отдельная поправка.","Pēc noklusējuma divas kārtas; jaunas funkcijas atsevišķi. Viena kārta ir saskaņots labojumu saraksts, nevis tikai viens labojums."],["Если задержу материалы?","Ja kavēšu materiālus?","Срок может продлиться, об этом сообщим письменно. Когда материалы будут готовы, обновим план; задержка клиента не превращается в нарушение срока исполнителем.","Termiņš var pagarināties; par to informēsim rakstiski. Kad materiāli būs gatavi, atjaunosim plānu; klienta kavējums nav izpildītāja termiņa pārkāpums."],["Если вы опоздаете?","Ja jūs kavēsiet termiņu?","Разберём причину и дальнейшие действия; автоматический штраф не обещаем. Если возникнет задержка с нашей стороны, сообщим о ней и предложим дальнейший план письменно.","Izvērtēsim iemeslu un tālāko rīcību; automātisku līgumsodu nesolām. Ja kavējums būs mūsu pusē, par to paziņosim un rakstiski piedāvāsim turpmāko plānu."],["Как проходит приёмка?","Kā notiek pieņemšana?","7 рабочих дней на проверку и замечания; затем процедура напоминания. Проверяете согласованные функции и сообщаете конкретные замечания; скрытые недостатки этим сроком не отменяются.","7 darbdienas pārbaudei un piezīmēm; pēc tam atgādinājuma kārtība. Pārbaudāt saskaņotās funkcijas un sniedzat konkrētas piezīmes; slēptie trūkumi ar šo termiņu netiek izslēgti."],["Можно запускать поэтапно?","Vai var palaist pa posmiem?","Да, если этапы заранее согласованы. Этапы и критерии их готовности лучше записать в задании до старта.","Jā, ja posmi ir iepriekš saskaņoti. Posmus un to pabeigšanas kritērijus labāk ierakstīt uzdevumā pirms sākuma."]]],["Договор и гарантии","Līgums un garantijas",[["Будет договор?","Vai būs līgums?","Да, с приложением о работах, сроках и цене. В нём фиксируем не только цену, но и объём работ, порядок оплаты, приёмки и поддержки.","Jā, ar pielikumu par darbiem, termiņiem un cenu. Tajā fiksējam ne tikai cenu, bet arī darbu apjomu, apmaksas, pieņemšanas un atbalsta kārtību."],["Кто юридический исполнитель?","Kas juridiski sniedz pakalpojumu?","Актуальные реквизиты будут в договоре; уточним перед подписанием. Перед подписанием вы увидите точные данные стороны, с которой заключаете договор.","Aktuālie rekvizīti būs līgumā; precizēsim pirms parakstīšanas. Pirms parakstīšanas redzēsiet precīzus tās puses datus, ar kuru slēdzat līgumu."],["Вы зарегистрированы в Латвии?","Vai esat reģistrēti Latvijā?","Предоставим подтверждённые регистрационные данные перед договором. Проверяемые реквизиты предоставим до оплаты; не просим полагаться только на устное обещание.","Pirms līguma sniegsim apstiprinātus reģistrācijas datus. Pārbaudāmus rekvizītus sniegsim pirms apmaksas; nelūdzam paļauties tikai uz mutisku solījumu."],["Можно договор до оплаты?","Vai var saņemt līgumu pirms maksājuma?","Да, сначала согласуем условия, затем первый платёж. Вы сможете спокойно прочитать условия и задать вопросы по спорным пунктам.","Jā, vispirms saskaņojam nosacījumus, tad pirmo maksājumu. Varēsiet mierīgi izlasīt nosacījumus un uzdot jautājumus par neskaidrajiem punktiem."],["На каком языке договор?","Kādā valodā ir līgums?","Основной текст на латышском, русский перевод информационный. Если понадобится пояснение на русском, поможем разобраться, но юридически важна согласованная латышская редакция.","Pamatteksts latviešu valodā, tulkojums krieviski informatīvs. Ja vajadzīgs skaidrojums krieviski, palīdzēsim, bet juridiski svarīga ir saskaņotā latviešu redakcija."],["Если результат не устроит?","Ja rezultāts neapmierinās?","Вы сможете проверить готовый сайт и сообщить, что именно не соответствует согласованному заданию. Такие обоснованные замечания мы исправляем без дополнительной оплаты. Просим описать расхождения с утверждённым заданием — это помогает отделить дефекты от новых пожеланий.","Jūs varēsiet pārbaudīt gatavo vietni un norādīt, kas tieši neatbilst saskaņotajam uzdevumam. Šādus pamatotus trūkumus novērsīsim bez papildu maksas. Lūdzam aprakstīt neatbilstības apstiprinātajam uzdevumam — tas palīdz atšķirt trūkumus no jaunām vēlmēm."],["Можно отказаться после старта?","Vai var atteikties pēc sākuma?","Возможен расчёт за фактически выполненную работу; детали по договору. Порядок расчёта зависит от того, какие работы уже выполнены и принят ли результат.","Iespējams norēķins par faktiski paveikto; detaļas pēc līguma. Norēķinu kārtība atkarīga no paveiktajiem darbiem un tā, vai rezultāts ir pieņemts."],["Вернёте деньги за незавершённое?","Vai atmaksāsiet par nepabeigto?","Переплата за невыполненные работы возвращается после расчёта. Мы покажем расчёт выполненных и невыполненных работ, чтобы возврат был понятным.","Pārmaksu par neizpildītiem darbiem atmaksā pēc aprēķina. Parādīsim paveikto un nepaveikto darbu aprēķinu, lai atmaksa būtu saprotama."],["Если уйду через три месяца?","Ja pārtraukšu pēc trim mēnešiem?","Зависит от готовности и приёмки сайта; дадим расчёт. При незавершённом проекте оплачивается надлежащим образом выполненная часть, а переплата возвращается.","Atkarīgs no vietnes pabeigšanas un pieņemšanas; sniegsim aprēķinu. Nepabeigtā projektā apmaksā pienācīgi paveikto daļu, bet pārmaksu atmaksā."],["Оплачивать оставшиеся месяцы?","Vai jāmaksā atlikušie mēneši?","Не обязательно все оставшиеся платежи. Если сайт уже завершён и принят, нужно будет погасить неоплаченную часть стоимости разработки, но не оплачивать поддержку, которая ещё не оказана. Точный расчёт покажем письменно. Это не штраф и не оплата будущих услуг, а расчёт за уже выполненную разработку.","Ne vienmēr jāveic visi atlikušie maksājumi. Ja vietne jau ir pabeigta un pieņemta, jāsamaksā neapmaksātā izstrādes daļa, bet ne par vēl nesniegtu atbalstu. Precīzu aprēķinu sniegsim rakstiski. Tas nav sods vai maksa par nākotnes pakalpojumiem, bet norēķins par jau paveikto izstrādi."],["Есть штраф за расторжение?","Vai ir sods par līguma izbeigšanu?","В проекте Start отдельного штрафа нет; расчёт за работу сохраняется. Чтобы избежать недоразумений, сумму и основания расчёта подтвердим письменно.","Start projektā atsevišķa soda nav; samaksa par paveikto saglabājas. Lai nerastos pārpratumi, summu un aprēķina pamatu apstiprināsim rakstiski."],["Если найдём ошибки?","Ja atklāsim kļūdas?","Наши ошибки и несоответствия заданию исправляем без доплаты. Сообщите, где возникает ошибка и как её воспроизвести, — так быстрее определим исправление.","Mūsu kļūdas un neatbilstības uzdevumam labojam bez piemaksas. Pastāstiet, kur rodas kļūda un kā to atkārtot, — tā ātrāk noteiksim labojumu."],["Кто отвечает за простой?","Kas atbild par dīkstāvi?","Причину и ответственность оцениваем по договору и закону; 24/7 не гарантируем. Сначала выясним, связана ли проблема с нашим кодом, хостингом или сторонним сервисом.","Cēloni un atbildību vērtē pēc līguma un likuma; 24/7 negarantējam. Vispirms noskaidrosim, vai problēma saistīta ar mūsu kodu, hostingu vai trešās puses pakalpojumu."],["Если сайт взломают?","Ja vietni uzlauzīs?","Рассмотрим инцидент; меры и ответственность зависят от обстоятельств. Важно сразу сохранить сведения об инциденте и ограничить дальнейший доступ злоумышленника.","Izskatīsim incidentu; rīcība un atbildība atkarīga no apstākļiem. Svarīgi nekavējoties saglabāt informāciju par incidentu un ierobežot turpmāku nesankcionētu piekļuvi."],["Гарантируете безопасность?","Vai garantējat drošību?","Абсолютной гарантии нет; меры защиты согласуем. Обсудим доступы, обновления и резервные копии; ни один сайт нельзя объявить полностью неуязвимым.","Absolūtas garantijas nav; aizsardzības pasākumus saskaņosim. Apspriedīsim piekļuves, atjauninājumus un rezerves kopijas; nevienu vietni nevar uzskatīt par pilnīgi neievainojamu."],["Как решаются споры?","Kā risina strīdus?","Сначала письменные переговоры, затем по праву Латвии. Поэтому существенные договорённости и замечания лучше сохранять в переписке.","Vispirms rakstiskas sarunas, pēc tam saskaņā ar Latvijas tiesībām. Tāpēc būtiskās vienošanās un piezīmes vēlams saglabāt sarakstē."],["Договор на компанию?","Vai līgumu var slēgt uzņēmums?","Да, проект договора предназначен для B2B. Для договора понадобятся корректные реквизиты компании и уполномоченного представителя.","Jā, līguma projekts paredzēts B2B. Līgumam vajadzīgi pareizi uzņēmuma un pilnvarotā pārstāvja rekvizīti."],["Можно как частное лицо?","Vai var kā privātpersona?","Нужна другая редакция договора; уточним возможность. Для физических лиц действуют иные требования, поэтому сначала уточним формат заказа.","Nepieciešama cita līguma redakcija; iespēju precizēsim. Privātpersonām ir citas prasības, tāpēc vispirms precizēsim pasūtījuma veidu."]]],["Права и уход","Tiesības un sadarbības beigas",[["Кому принадлежит сайт?","Kam pieder vietne?","После оплаты разработки — бессрочная неисключительная лицензия; общие модули остаются у Lomenti. Это позволяет вам использовать сайт для бизнеса, развивать его и менять подрядчика; исключительные авторские права автоматически не передаются.","Pēc izstrādes apmaksas — beztermiņa neekskluzīva licence; kopīgie moduļi paliek Lomenti. Tas ļauj izmantot vietni uzņēmējdarbībā, to attīstīt un mainīt izstrādātāju; ekskluzīvas autortiesības automātiski netiek nodotas."],["Когда получу права?","Kad iegūšu tiesības?","После полной оплаты согласованной разработки. До полной оплаты порядок использования определяется договором, поэтому важно завершить расчёт за разработку.","Pēc pilnas saskaņotās izstrādes apmaksas. Līdz pilnai apmaksai izmantošanas kārtību nosaka līgums, tādēļ svarīgi pabeigt norēķinu par izstrādi."],["Можно к другому разработчику?","Vai var pāriet pie cita izstrādātāja?","Да, с учётом лицензий сторонних компонентов. Не нужно оставаться с Lomenti только ради доступа к своему сайту.","Jā, ievērojot trešo pušu komponentu licences. Nav jāpaliek pie Lomenti tikai tādēļ, lai saglabātu piekļuvi savai vietnei."],["Получим файлы?","Vai saņemsim failus?","При прекращении поддержки передаём доступные актуальные файлы и доступы. Передачу согласуем так, чтобы новый специалист мог разобраться в доступной структуре проекта.","Pārtraucot atbalstu, nododam pieejamos aktuālos failus un piekļuves. Nodošanu saskaņosim tā, lai jaunais speciālists varētu saprast pieejamo projekta struktūru."],["Домен на меня?","Vai domēns būs uz mana vārda?","Да, на заказчика. Это важно: вы сможете самостоятельно продлевать домен и управлять им.","Jā, uz pasūtītāja vārda. Tas ir svarīgi: varēsiet paši pagarināt domēnu un to pārvaldīt."],["Чей хостинг?","Kam pieder hostinga konts?","Аккаунт и оплата принадлежат заказчику. Мы можем помочь с первоначальной настройкой, но доступ и отношения с провайдером остаются у вас.","Konts un maksājumi ir pasūtītāja ziņā. Varam palīdzēt ar sākotnējo iestatīšanu, bet piekļuve un attiecības ar pakalpojumu sniedzēju paliek jums."],["Можно уйти с поддержки?","Vai var atteikties no atbalsta?","После первого года — письменно предупредив минимум за 30 дней. Предупреждение направляется письменно, чтобы обе стороны знали дату окончания поддержки.","Pēc pirmā gada — rakstiski brīdinot vismaz 30 dienas iepriekš. Brīdinājumu nosūta rakstiski, lai abas puses zinātu atbalsta beigu datumu."],["Что после 12 месяцев?","Kas notiek pēc 12 mēnešiem?","Поддержка продолжается за 50 €/мес. до прекращения по договору. Если захотите прекратить сопровождение, соблюдаем предусмотренный договором порядок уведомления.","Atbalsts turpinās par 50 €/mēn. līdz izbeigšanai pēc līguma. Ja vēlaties izbeigt atbalstu, ievērojam līgumā paredzēto paziņošanas kārtību."],["Можно редактировать самому?","Vai var rediģēt pašam?","Право изменения после оплаты есть; панель редактирования согласуется отдельно. Если нужна самостоятельная панель управления, обсудим её ещё на этапе задания.","Tiesības mainīt pēc apmaksas ir; rediģēšanas paneli saskaņo atsevišķi. Ja vajadzīgs pašapkalpošanās rediģēšanas panelis, apspriedīsim to jau uzdevuma posmā."],["Другой разработчик может менять код?","Vai cits izstrādātājs var mainīt kodu?","Да, в рамках лицензии и сторонних ограничений. Новый специалист сможет продолжить работу, но ответственность за его изменения не переносится автоматически на нас.","Jā, licences un trešo pušu ierobežojumu ietvaros. Jaunais speciālists var turpināt darbu, bet atbildība par viņa izmaiņām automātiski nepāriet uz mums."],["Используете мой дизайн повторно?","Vai atkārtoti izmantosiet manu dizainu?","Конфиденциальные материалы и бренд не переносим; общие модули повторно используем. Ваши логотипы, тексты и закрытая информация не становятся шаблоном для других клиентов.","Konfidenciālus materiālus un zīmolu nepārnesam; kopīgus moduļus varam izmantot atkārtoti. Jūsu logotipi, teksti un slēgtā informācija nekļūst par veidni citiem klientiem."],["Можно запретить портфолио?","Vai var aizliegt publicēt portfolio?","Условия публикации согласуем отдельно; без разрешения не обещаем публикацию. Согласие на публикацию проекта и отзывов лучше оформлять отдельно.","Publicēšanas nosacījumus saskaņosim atsevišķi; bez atļaujas publicēšanu nesolām. Piekrišanu projekta un atsauksmju publicēšanai vēlams noformēt atsevišķi."],["Перенос платный?","Vai pārcelšana maksā?","Файлы и разумные инструкции — без доплаты; миграция и адаптация отдельно. Перенос может требовать работы с новым сервером и настройками — её стоимость согласуем до начала.","Faili un saprātīgas instrukcijas — bez piemaksas; migrācija un pielāgošana atsevišķi. Pārcelšanai var būt vajadzīgs darbs ar jaunu serveri un iestatījumiem — cenu saskaņosim pirms sākuma."],["Что будет с данными?","Kas notiks ar datiem?","Передачу и удаление согласуем по договору и DPA. Если сайт обрабатывает данные посетителей, порядок их обработки и удаления определим отдельно.","Nodošanu un dzēšanu saskaņosim pēc līguma un DPA. Ja vietne apstrādā apmeklētāju datus, to apstrādes un dzēšanas kārtību noteiksim atsevišķi."]]],["Поддержка","Atbalsts",[["Что входит в поддержку?","Kas ietilpst atbalstā?","2 небольшие правки контента в месяц, резервные копии и согласованное сопровождение. Новые разделы и сложные функции не входят автоматически в две небольшие правки.","2 nelieli satura labojumi mēnesī, rezerves kopijas un saskaņots atbalsts. Jaunas sadaļas un sarežģītas funkcijas automātiski neietilpst divos nelielajos labojumos."],["Что такое небольшая правка?","Kas ir neliels labojums?","Замена текста, фото или контактов без новых функций. Например, можно заменить номер телефона или короткое описание услуги без переделки дизайна.","Teksta, foto vai kontaktu maiņa bez jaunām funkcijām. Piemēram, var nomainīt tālruņa numuru vai īsu pakalpojuma aprakstu, nepārveidojot dizainu."],["Сколько правок в месяц?","Cik labojumu mēnesī?","Две небольшие правки. Если изменений больше, согласуем объём и цену дополнительных работ до их выполнения.","Divi nelieli labojumi. Ja izmaiņu ir vairāk, pirms veikšanas saskaņosim papildu darbu apjomu un cenu."],["Можно заменить фото и текст?","Vai var mainīt foto un tekstu?","Да, в пределах небольших правок. Пришлите новый материал и укажите, на какой странице его заменить.","Jā, nelielu labojumu ietvaros. Nosūtiet jauno materiālu un norādiet, kurā lapā to nomainīt."],["Можно изменить телефон и адрес?","Vai var mainīt telefonu un adresi?","Да, это небольшая правка. Достаточно отправить актуальные данные и место на сайте, где их нужно обновить.","Jā, tas ir neliels labojums. Pietiek nosūtīt aktuālos datus un vietu vietnē, kur tie jāatjaunina."],["Если правок больше двух?","Ja vajag vairāk par diviem labojumiem?","Дополнительные работы оценим и согласуем письменно. Необязательно заказывать большой пакет: можем оценить только нужные вам изменения.","Papilddarbus novērtēsim un saskaņosim rakstiski. Nav obligāti jāpasūta liela pakete: varam novērtēt tikai nepieciešamās izmaiņas."],["Правки копятся?","Vai labojumi uzkrājas?","Нет, неиспользованные правки не переносятся. То есть два изменения предусмотрены в каждом месяце отдельно, а не суммируются за год.","Nē, neizmantotie labojumi nepārceļas. Tas nozīmē, ka katrā mēnesī paredzēti divi labojumi, nevis tie uzkrājas gada laikā."],["Как быстро отвечаете?","Cik ātri atbildat?","Стремимся ответить в течение 48 часов, без гарантии фиксированного срока. При обращении полезно сразу указать адрес сайта и суть вопроса, чтобы мы быстрее разобрались.","Cenšamies atbildēt 48 stundu laikā, negarantējot noteiktu termiņu. Vēršoties pie mums, norādiet vietnes adresi un problēmas būtību, lai ātrāk to izskatītu."],["Поддержка по выходным?","Vai atbalsts ir brīvdienās?","Сообщение можно отправить; круглосуточной поддержки нет. Если вопрос срочный, обозначьте это в сообщении, но не рассчитывайте на гарантированный ответ ночью.","Ziņu var nosūtīt; diennakts atbalsta nav. Ja jautājums ir steidzams, norādiet to ziņā, bet nepaļaujieties uz garantētu atbildi naktī."],["Если сайт упал?","Ja vietne nedarbojas?","Сообщите нам; серьёзные сбои приоритетны, срок восстановления не гарантируем. Укажите, когда заметили проблему и что именно не открывается; проверим причину и возможные действия.","Ziņojiet mums; nopietnas kļūmes ir prioritāras, atjaunošanas laiku negarantējam. Norādiet, kad pamanījāt problēmu un kas tieši neatveras; pārbaudīsim cēloni un iespējamo rīcību."],["Делаете копии?","Vai veidojat rezerves kopijas?","Для Start — не реже раза в 7 дней, храним минимум 4 последние отдельно при технической возможности. Резервные копии помогают восстановлению, но не заменяют отдельную проверку работоспособности сайта.","Start — vismaz reizi 7 dienās, glabājam vismaz 4 pēdējās atsevišķi, ja tehniski iespējams. Rezerves kopijas palīdz atjaunošanā, bet neaizstāj atsevišķu vietnes darbības pārbaudi."],["Можно восстановить?","Vai var atjaunot vietni?","Проверяем пригодность копий, но отсутствие потерь не гарантируем. Восстановление зависит от наличия исправной копии и от того, что произошло после её создания.","Pārbaudām kopiju derīgumu, bet datu zuduma neesamību negarantējam. Atjaunošana atkarīga no derīgas kopijas un izmaiņām pēc tās izveides."],["Технические обновления?","Vai veicat tehniskus atjauninājumus?","Объём определён приложением; дополнительные работы отдельно. Например, обновления сторонних платформ и плагинов могут требовать отдельной оценки совместимости.","Apjoms noteikts pielikumā; papilddarbi atsevišķi. Piemēram, trešo pušu platformu un spraudņu atjauninājumiem var būt vajadzīgs savietojamības izvērtējums."],["Исправление ошибок платное?","Vai kļūdu labošana maksā?","Наши ошибки в согласованном задании исправляем бесплатно. Важно различать ошибку в согласованной работе и просьбу добавить новую возможность.","Mūsu kļūdas saskaņotajā uzdevumā labojam bez maksas. Svarīgi atšķirt kļūdu saskaņotajā darbā no lūguma pievienot jaunu funkciju."],["Можно поставить поддержку на паузу?","Vai var apturēt atbalstu uz laiku?","Автоматического права нет, обсудим индивидуально. Если поддержка временно не нужна, напишите нам — проверим, какой вариант допускают условия договора.","Automātisku tiesību nav, apspriedīsim individuāli. Ja atbalsts uz laiku nav vajadzīgs, uzrakstiet mums — pārbaudīsim, ko pieļauj līgums."]]],["Магазины и доработки","Veikali un pielāgojumi",[["Создаёте магазины?","Vai veidojat e-veikalus?","Да, как отдельные проекты. Сначала определим, нужен ли вам простой каталог или полноценная корзина, оплата и доставка.","Jā, kā atsevišķus projektus. Vispirms noskaidrosim, vai vajadzīgs vienkāršs katalogs vai pilns grozs, apmaksa un piegāde."],["Цена магазина?","Cik maksā e-veikals?","Индивидуально по функциям, товарам и интеграциям. Для расчёта важны ассортимент, управление товарами, способы оплаты и доставка.","Individuāli pēc funkcijām, precēm un integrācijām. Aprēķinam svarīgs sortiments, preču pārvaldība, maksājumu un piegādes veidi."],["Можно оплату картой?","Vai var pievienot karšu maksājumus?","Да, при согласовании сервиса и интеграции. Платёжный провайдер может взимать собственные комиссии, которые не входят в разработку.","Jā, saskaņojot pakalpojumu un integrāciju. Maksājumu pakalpojumu sniedzējs var piemērot savas komisijas, kas nav iekļautas izstrādē."],["Работаете с Shopify?","Vai strādājat ar Shopify?","Проверим выбранную платформу и возможность реализации. У платформы могут быть отдельные тарифы и ограничения, поэтому уточним ваш текущий тариф и задачу.","Pārbaudīsim izvēlēto platformu un īstenošanas iespēju. Platformai var būt atsevišķi tarifi un ierobežojumi, tādēļ precizēsim jūsu plānu un vajadzību."],["Можно Omniva или DPD?","Vai var pievienot Omniva vai DPD?","Оценим техническую возможность и стоимость. Нужно уточнить регионы доставки, тарифы и способ передачи заказов перевозчику.","Izvērtēsim tehnisko iespēju un cenu. Jāprecizē piegādes reģioni, tarifi un pasūtījumu nodošanas veids pārvadātājam."],["Можно импортировать товары?","Vai var importēt preces?","Оценим по объёму и формату исходных данных. Лучше заранее проверить пример файла, чтобы избежать потери описаний, цен и изображений.","Izvērtēsim pēc apjoma un datu formāta. Labāk iepriekš pārbaudīt faila paraugu, lai nezaudētu aprakstus, cenas un attēlus."],["Сколько товаров?","Cik daudz preču?","Количество определяется проектом. Важно не только количество товаров, но и число вариантов, категорий и частота обновлений.","Daudzumu nosaka projektā. Svarīgs ir ne tikai preču skaits, bet arī variantu un kategoriju skaits un atjaunināšanas biežums."],["Складской учёт?","Vai var integrēt noliktavas uzskaiti?","Проверим совместимость и оценим отдельно. Уточним, с какой системой вы работаете и какие данные должны синхронизироваться.","Pārbaudīsim savietojamību un vērtēsim atsevišķi. Precizēsim, kuru sistēmu izmantojat un kādi dati jāsinhronizē."],["Кто отвечает за возвраты?","Kas atbild par preču atgriešanu?","Владелец магазина отвечает за продажи, цены, доставку и возвраты. Мы разрабатываем техническую часть, а коммерческие правила магазина определяет его владелец.","Veikala īpašnieks atbild par pārdošanu, cenām, piegādi un atgriešanu. Mēs izstrādājam tehnisko daļu, bet veikala komercnoteikumus nosaka tā īpašnieks."],["Платёжные сервисы отдельно?","Vai maksājumu servisi maksā atsevišķi?","Да, сторонние расходы отдельно. До выбора сервиса покажем, какие платежи относятся к разработке, а какие — к провайдеру.","Jā, trešo pušu izmaksas ir atsevišķas. Pirms pakalpojuma izvēles parādīsim, kuri maksājumi ir par izstrādi un kuri — pakalpojumu sniedzējam."],["Можно улучшить готовый магазин?","Vai var uzlabot esošu veikalu?","Да, после технической оценки. Проверим текущую платформу и предложим точечные улучшения, не навязывая полную переделку.","Jā, pēc tehniskā izvērtējuma. Pārbaudīsim esošo platformu un piedāvāsim konkrētus uzlabojumus, neuzspiežot pilnu pārbūvi."],["Как платят за индивидуальный проект?","Kā apmaksā individuālu projektu?","Стандартно 50% / 30% / 20% по этапам, если не согласовано иначе. Этапы, результаты и даты платежей укажем в индивидуальном договоре.","Parasti 50% / 30% / 20% pa posmiem, ja nav saskaņots citādi. Posmus, rezultātus un maksājumu datumus norādīsim individuālajā līgumā."],["Поддержка магазина включена?","Vai veikala atbalsts iekļauts?","Нет, согласуется отдельно. Для магазина отдельно обсудим обновления, исправления и ответственность за сторонние сервисы.","Nē, to saskaņo atsevišķi. Veikalam atsevišķi apspriedīsim atjauninājumus, labojumus un atbildību par trešo pušu pakalpojumiem."]]],["AI-чат-бот","AI čatbots",[["Что умеет AI-бот?","Ko prot AI čatbots?","Отвечает на информационные вопросы по согласованным источникам. Например, может объяснять услуги, режим работы и порядок обращения, если эти сведения предоставлены.","Atbild uz informatīviem jautājumiem no saskaņotiem avotiem. Piemēram, var izskaidrot pakalpojumus, darba laiku un saziņas kārtību, ja šī informācija ir pieejama."],["Чем отличается от обычного чата?","Ar ko atšķiras no parasta čata?","Понимает свободные вопросы, а не только кнопки. Но даже AI-боту нужны проверенные данные и правила, когда лучше передать вопрос сотруднику.","Saprot brīvi formulētus jautājumus, ne tikai pogas. Taču arī AI botam vajadzīgi pārbaudīti dati un noteikumi, kad jautājumu nodot darbiniekam."],["Сколько стоит AI-бот?","Cik maksā AI čatbots?","Здесь стоимость зависит от того, на какие вопросы бот должен отвечать и какие функции выполнять. Мы сначала уточним ваши задачи, а затем предложим подходящее решение и цену. После обсуждения подготовим перечень функций, источников данных и ожидаемых расходов.","Cena ir atkarīga no tā, uz kādiem jautājumiem botam jāatbild un kādas funkcijas tam jāpilda. Vispirms precizēsim jūsu vajadzības, pēc tam piedāvāsim risinājumu un cenu. Pēc sarunas sagatavosim funkciju, datu avotu un paredzamo izmaksu sarakstu."],["Есть абонентская плата?","Vai ir abonēšanas maksa?","Поддержка, API и сервисы рассчитываются отдельно. Отдельно уточним плату за использование модели, объём обращений и техническое сопровождение.","Atbalstu, API un pakalpojumus aprēķina atsevišķi. Atsevišķi precizēsim modeļa izmantošanas maksu, pieprasījumu apjomu un tehnisko atbalstu."],["Отвечает на RU и LV?","Vai atbild RU un LV?","Можно настроить оба языка и проверить тестами. Проверим типичные вопросы на обоих языках до запуска, чтобы избежать неверных формулировок.","Var iestatīt abas valodas un pārbaudīt testos. Pirms palaišanas pārbaudīsim tipiskus jautājumus abās valodās, lai izvairītos no kļūdainiem formulējumiem."],["Работает круглосуточно?","Vai darbojas visu diennakti?","Может быть доступен постоянно, но 24/7 не гарантируем. Доступность зависит также от сайта, интернета и внешних сервисов, поэтому абсолютной гарантии нет.","Var būt pieejams nepārtraukti, bet 24/7 negarantējam. Pieejamība ir atkarīga arī no vietnes, interneta un ārējiem pakalpojumiem, tādēļ absolūtas garantijas nav."],["Может принимать заявки?","Vai var saņemt pieteikumus?","Можно настроить передачу на email или CRM с защитой данных. До запуска согласуем, какие поля собирать, кому передавать заявку и как защищать данные.","Var iestatīt nodošanu uz e-pastu vai CRM ar datu aizsardzību. Pirms palaišanas saskaņosim, kādus laukus vākt, kam nodot pieteikumu un kā aizsargāt datus."],["Передаёт человеку?","Vai nodod jautājumu cilvēkam?","Да, по согласованному каналу. Уточним, в каких случаях бот должен остановиться и предложить связь с сотрудником.","Jā, pa saskaņotu kanālu. Precizēsim, kad botam jāpārtrauc atbildēt un jāpiedāvā saziņa ar darbinieku."],["Подключите к готовому сайту?","Vai pieslēgsiet esošai vietnei?","Проверим совместимость. Для этого нужно проверить платформу сайта, способ встраивания и ограничения безопасности.","Pārbaudīsim savietojamību. Tam jāpārbauda vietnes platforma, ievietošanas veids un drošības ierobežojumi."],["Откуда берёт информацию?","No kurienes ņem informāciju?","Из согласованных источников знаний. Информацию о ценах и условиях нужно регулярно обновлять, иначе ответы могут устареть.","No saskaņotiem zināšanu avotiem. Informācija par cenām un nosacījumiem regulāri jāatjaunina, citādi atbildes var novecot."],["Может ошибаться?","Vai var kļūdīties?","Да; поэтому нужны тесты и передача сложных вопросов человеку. Поэтому для важных решений не стоит полагаться только на ответ бота без проверки человеком.","Jā; tāpēc vajadzīgi testi un sarežģītu jautājumu nodošana cilvēkam. Tādēļ svarīgus lēmumus nevajadzētu balstīt tikai uz bota atbildi bez cilvēka pārbaudes."],["Если ответит неправильно?","Ja atbildēs nepareizi?","Риски и ответственность рассматриваются по условиям и обстоятельствам. Ошибку разберём, проверим источник информации и при необходимости изменим настройки.","Riskus un atbildību vērtē pēc nosacījumiem un apstākļiem. Kļūdu izskatīsim, pārbaudīsim informācijas avotu un vajadzības gadījumā mainīsim iestatījumus."],["Может оформлять заказы?","Vai var noformēt pasūtījumus?","Наш информационный бот не заключает сделки и не принимает деньги. Если нужна полноценная автоматизация заказов, это уже отдельный проект с другими требованиями.","Mūsu informatīvais bots neslēdz darījumus un nepieņem naudu. Ja vajadzīga pilna pasūtījumu automatizācija, tas ir atsevišķs projekts ar citām prasībām."],["Кто видит переписки?","Kas redz sarakstes?","Зависит от архитектуры; постоянный архив у Lomenti по умолчанию не создаётся. Перед запуском согласуем доступ сотрудников, журналирование и правила хранения сообщений.","Atkarīgs no arhitektūras; Lomenti pēc noklusējuma neveido pastāvīgu arhīvu. Pirms palaišanas saskaņosim darbinieku piekļuvi, žurnalēšanu un ziņu glabāšanas noteikumus."],["Где хранятся данные?","Kur glabājas dati?","Провайдеры и сроки фиксируются до запуска в DPA. Без конкретной архитектуры нельзя обещать определённую страну хранения или срок удаления.","Pakalpojumu sniedzējus un termiņus fiksē DPA pirms palaišanas. Bez konkrētas arhitektūras nevar solīt noteiktu glabāšanas valsti vai dzēšanas termiņu."],["Соответствует GDPR?","Vai atbilst GDPR?","Конфигурацию и DPA проверяем до запуска; без проверки гарантий нет. Проверим, какие персональные данные обрабатываются, кто является обработчиком и какие документы нужны.","Konfigurāciju un DPA pārbaudām pirms palaišanas; bez pārbaudes garantiju nav. Pārbaudīsim, kādi personas dati tiek apstrādāti, kurš ir apstrādātājs un kādi dokumenti vajadzīgi."],["Можно протестировать?","Vai var izmēģināt?","Демонстрацию обсудим; тестирование перед приёмкой предусмотрено. В тестах полезно проверить сложные вопросы, ошибки, переключение языка и передачу оператору.","Demonstrāciju apspriedīsim; testēšana pirms pieņemšanas paredzēta. Testos noder pārbaudīt sarežģītus jautājumus, kļūdas, valodu maiņu un nodošanu operatoram."],["Как обновлять информацию?","Kā atjaunot informāciju?","Порядок и цену обновлений согласуем в поддержке. Важно назначить человека, который сообщает об изменении услуг, цен и условий.","Atjaunināšanas kārtību un cenu saskaņosim atbalsta nosacījumos. Svarīgi nozīmēt personu, kura ziņo par pakalpojumu, cenu un nosacījumu izmaiņām."]]],["О Lomenti","Par Lomenti",[["Как давно работаете?","Cik ilgi strādājat?","Развиваем Lomenti; точную дату деятельности уточним. Вместо неподтверждённых дат лучше покажем, какие решения уже можем продемонстрировать.","Attīstām Lomenti; precīzu darbības sākumu precizēsim. Nepārbaudītu datumu vietā labāk parādīsim risinājumus, ko jau varam demonstrēt."],["Сколько сайтов сделали?","Cik vietņu esat izveidojuši?","Покажем подтверждённые проекты и концепты, не смешивая их. Если вас интересует конкретная задача, подберём наиболее близкий по функциональности пример.","Parādīsim apstiprinātus projektus un konceptus, tos nejaucot. Ja interesē konkrēts uzdevums, piemeklēsim pēc funkcijām tuvāko piemēru."],["Есть реальные клиенты?","Vai ir īsti klienti?","Предоставим только разрешённые к показу сведения. Мы не будем представлять демонстрационные концепты как оплаченные клиентские проекты.","Sniegsim tikai informāciju, ko drīkst publiskot. Demonstrācijas konceptus neuzdosim par apmaksātiem klientu projektiem."],["Есть отзывы?","Vai ir atsauksmes?","Направим доступные опубликованные отзывы, если они есть. Если публичных отзывов пока нет, так и скажем и предложим посмотреть демонстрацию.","Nosūtīsim pieejamās publicētās atsauksmes, ja tādas ir. Ja publisku atsauksmju vēl nav, to pateiksim un piedāvāsim apskatīt demonstrāciju."],["Почему так дёшево?","Kāpēc tik lēti?","Start ограничен понятным объёмом, без ненужных функций. Стоимость ниже за счёт чётких границ Start: до пяти страниц и без сложных интеграций.","Start ir skaidri ierobežots apjoms bez liekām funkcijām. Cena ir zemāka skaidra Start apjoma dēļ: līdz piecām lapām un bez sarežģītām integrācijām."],["Если Lomenti закроется?","Ja Lomenti pārtrauks darbību?","Домен и хостинг ваши, права и файлы передаются по договору. Это снижает зависимость от одного исполнителя и помогает продолжить работу с другим специалистом.","Domēns un hostings pieder jums; tiesības un failus nodod pēc līguma. Tas mazina atkarību no viena izstrādātāja un palīdz turpināt darbu ar citu speciālistu."],["Кто мой контакт?","Kas būs mana kontaktpersona?","Укажем ответственного в документах. Для удобства согласуем основной канал связи и порядок передачи задач.","Atbildīgo norādīsim dokumentos. Ērtībai saskaņosim galveno saziņas kanālu un uzdevumu nodošanas kārtību."],["Можно поговорить с разработчиком?","Vai var runāt ar izstrādātāju?","Передадим вопрос и согласуем удобный контакт. Передадим конкретный технический вопрос, чтобы разговор был предметным.","Nodosim jautājumu un saskaņosim ērtu saziņu. Nodosim konkrēto tehnisko jautājumu, lai saruna būtu mērķtiecīga."],["Есть опыт в моей отрасли?","Vai ir pieredze manā nozarē?","Покажем только подтверждённые подходящие примеры. Если прямого примера в вашей отрасли нет, покажем похожие задачи, не выдавая их за отраслевой опыт.","Parādīsim tikai apstiprinātus atbilstošus piemērus. Ja nav tieša piemēra jūsu nozarē, parādīsim līdzīgus uzdevumus, neuzdodot tos par nozares pieredzi."],["Почему выбрать вас?","Kāpēc izvēlēties jūs?","Понятный тариф, письменные условия, согласование задач и поддержка. Предлагаем начать с ваших задач и согласовать только те функции, которые действительно нужны.","Skaidrs tarifs, rakstiski nosacījumi, uzdevumu saskaņošana un atbalsts. Piedāvājam sākt ar jūsu vajadzībām un saskaņot tikai patiešām nepieciešamās funkcijas."]]],["Начало сотрудничества","Sadarbības sākums",[["Что дальше, если согласен?","Kas tālāk, ja piekrītu?","Уточним задачи и контакт, затем подготовим предложение. Уточним, какие услуги вы предлагаете, есть ли сайт сейчас и какой результат для вас важен.","Precizēsim vajadzības un kontaktu, tad sagatavosim piedāvājumu. Precizēsim jūsu pakalpojumus, vai vietne jau ir un kāds rezultāts jums svarīgs."],["Обязательна встреча?","Vai obligāti jātiekas?","Нет, при достаточной информации можно всё согласовать письменно. Созвон или встречу предложим только если это действительно поможет решить сложный вопрос.","Nē, ja informācijas pietiek, visu var saskaņot rakstiski. Zvanu vai tikšanos piedāvāsim tikai tad, ja tas tiešām palīdzēs atrisināt sarežģītu jautājumu."],["Можно всё по email?","Vai visu var e-pastā?","Да, конечно. Мы можем обсудить задачи, согласовать предложение и оформить необходимые документы по электронной почте. В переписке удобно сохранить согласованные требования, цены и сроки.","Jā, protams. Varam pārrunāt vajadzības, saskaņot piedāvājumu un nokārtot dokumentus e-pastā. Sarakstē ērti saglabāt saskaņotās prasības, cenas un termiņus."],["Сначала покажете дизайн?","Vai vispirms parādīsiet dizainu?","Формат предварительной демонстрации обсудим; бесплатный дизайн не обещаем. После согласования задания подготовим первый вариант в предусмотренном проектом порядке.","Iepriekšējas demonstrācijas formu apspriedīsim; bezmaksas dizainu nesolām. Pēc uzdevuma saskaņošanas sagatavosim pirmo variantu projektā paredzētajā kārtībā."],["Можно индивидуальное предложение?","Vai var individuālu piedāvājumu?","Да, после уточнения задач. Чтобы предложение было точным, расскажите о количестве страниц, языках и нужных функциях.","Jā, pēc vajadzību precizēšanas. Lai piedāvājums būtu precīzs, pastāstiet par lapu skaitu, valodām un vajadzīgajām funkcijām."],["Какие материалы нужны?","Kādi materiāli vajadzīgi?","Информация о компании, услуги, контакты, фото, тексты и пожелания. Если материалов много, можно начать с основных и составить список недостающего.","Uzņēmuma informācija, pakalpojumi, kontakti, foto, teksti un vēlmes. Ja materiālu ir daudz, var sākt ar galveno un izveidot trūkstošā sarakstu."],["Когда договор и счёт?","Kad būs līgums un rēķins?","После согласования условий; дату уточним. До первого платежа у вас будет возможность ознакомиться с условиями и задать вопросы.","Pēc nosacījumu saskaņošanas; datumu precizēsim. Pirms pirmā maksājuma varēsiet iepazīties ar nosacījumiem un uzdot jautājumus."],["Можно начать с малого?","Vai var sākt ar nelielu projektu?","Да, Start — до пяти информационных страниц. Если позже понадобится расширение, его можно согласовать отдельным этапом.","Jā, Start — līdz piecām informatīvām lapām. Ja vēlāk vajadzēs paplašinājumu, to varēs saskaņot atsevišķā posmā."],["Кто согласует изменения?","Kas saskaņo izmaiņas?","Назначенные контактные лица, письменно. Лучше назначить одного ответственного с вашей стороны, чтобы не получать противоречивые замечания.","Norādītās kontaktpersonas, rakstiski. Labāk nozīmēt vienu atbildīgo no jūsu puses, lai nesaņemtu pretrunīgas piezīmes."],["Как передаётся сайт?","Kā nodod vietni?","Проверка, акт или email-подтверждение, файлы и доступы по договору. Перед передачей проверим согласованные функции и зафиксируем замечания или подтверждение приёмки.","Pārbaude, akts vai e-pasta apstiprinājums, faili un piekļuves pēc līguma. Pirms nodošanas pārbaudīsim saskaņotās funkcijas un fiksēsim piezīmes vai pieņemšanas apstiprinājumu."]]]];
let faqQuery='',faqCategory=-1;
function renderFaq(){
 const app=document.getElementById('app');app.replaceChildren();
 const ru=language==='ru';const back=document.createElement('button');back.className='back';back.textContent=ru?'← К сценариям':'← Pie scenārijiem';back.onclick=()=>{window.faqOpen=false;scenario=null;path=[];render()};app.append(back);
 const h=document.createElement('h1');h.textContent=ru?'Вопросы клиентов':'Klientu jautājumi';app.append(h);
 const info=document.createElement('p');info.className='intro';info.textContent=ru?'Ответы по проекту договора от 03.11.2026. Условия, отмеченные для согласования, уточняйте у команды.':'Atbildes pēc 03.11.2026. līguma projekta. Nesaskaņotos nosacījumus precizējiet komandā.';app.append(info);
 const search=document.createElement('input');search.type='search';search.className='faq-search';search.placeholder=ru?'Поиск по вопросам и ответам…':'Meklēt jautājumos un atbildēs…';search.value=faqQuery;search.setAttribute('aria-label',search.placeholder);app.append(search);
 const categories=document.createElement('div');categories.className='faq-cats';app.append(categories);
 const list=document.createElement('div');list.className='faq-results';app.append(list);
 function update(){categories.replaceChildren();const all=document.createElement('button');all.className='choice'+(faqCategory===-1?' active':'');all.textContent=ru?'Все темы':'Visas tēmas';all.onclick=()=>{faqCategory=-1;update()};categories.append(all);
 FAQ_GROUPS.forEach((g,i)=>{const b=document.createElement('button');b.className='choice'+(faqCategory===i?' active':'');b.textContent=g[ru?0:1];b.onclick=()=>{faqCategory=faqCategory===i?-1:i;update()};categories.append(b)});
 list.replaceChildren();const q=faqQuery.trim().toLocaleLowerCase();let shown=0;
 FAQ_GROUPS.forEach((g,i)=>{if(faqCategory!==-1&&faqCategory!==i)return;const matched=g[2].filter(row=>!q||[row[0],row[1],row[2],row[3],g[0],g[1]].join(' ').toLocaleLowerCase().includes(q));if(!matched.length)return;const title=document.createElement('h2');title.className='faq-heading';title.textContent=g[ru?0:1]+' · '+matched.length;list.append(title);matched.forEach(row=>{shown++;const item=document.createElement('details');item.className='faq-item';const summary=document.createElement('summary');summary.textContent=row[ru?0:1];const answer=document.createElement('p');answer.textContent=row[ru?2:3];item.append(summary,answer);list.append(item)})});if(!shown){const empty=document.createElement('p');empty.className='intro';empty.textContent=ru?'Ничего не найдено':'Nekas nav atrasts';list.append(empty)}
 }
 search.addEventListener('input',()=>{faqQuery=search.value;update()});update();
}
